27	/// Result of parsing positional `..` notation.
28	///
29	/// Counts are `Some(0)` for closed sides and `None` for open sides.
30	/// Open sides become unlimited unless a positional count is applied later.
31	#[derive(Debug, Clone, PartialEq, Eq)]
32	pub struct DotSpec {
33	    /// The bare revision (without `..`).
34	    pub rev: String,
35	    /// Descendant count: `None` = open, `Some(0)` = closed.
36	    pub desc_count: Option<usize>,
37	    /// Ancestor count: `None` = open, `Some(0)` = closed.
38	    pub anc_count: Option<usize>,
39	}
40	
41	/// Parse a positional REV string for `..` notation.
42	///
43	/// Returns the bare revision with open/closed counts per side.
44	/// `None` means the side had dots (open for expansion);
45	/// `Some(0)` means no dots on that side (closed).
46	/// Actual counts are applied later from positional args.
47	pub fn parse_dot_rev(rev: &str) -> DotSpec {
48	    if let Some(inner) = rev.strip_prefix("..").and_then(|s| s.strip_suffix("..")) {
49	        DotSpec {
50	            rev: inner.to_string(),
51	            desc_count: None,
52	            anc_count: None,
53	        }
54	    } else if let Some(inner) = rev.strip_prefix("..") {
55	        DotSpec {
56	            rev: inner.to_string(),
57	            desc_count: None,
58	            anc_count: Some(0),
59	        }
60	    } else if let Some(inner) = rev.strip_suffix("..") {
61	        DotSpec {
62	            rev: inner.to_string(),
63	            desc_count: Some(0),
64	            anc_count: None,
65	        }
66	    } else {
67	        DotSpec {
68	            rev: rev.to_string(),
69	            desc_count: Some(0),
70	            anc_count: Some(0),
71	        }
72	    }
73	}
74	
75	/// Resolve positional and flag args into a `DotSpec` ready for `collect_ids`.
76	///
77	/// Handles: dot notation parsing, flag vs positional precedence,
78	/// count-means-total semantics (subtracts 1 for anchor).
79	pub fn resolve_spec(
80	    pos_rev: Option<&str>,
81	    pos_count: Option<usize>,
82	    flag_rev: &str,
83	    flag_limit: Option<usize>,
84	    default_rev: &str,
85	) -> DotSpec {
86	    let flag_rev_set = flag_rev != default_rev;
87	    let rev_str = if flag_rev_set {
88	        flag_rev
89	    } else {
90	        pos_rev.unwrap_or(default_rev) // OK: positional absent → fall back to CLI default
91	    };
92	    let mut spec = parse_dot_rev(rev_str);
93	
94	    let count = if flag_limit.is_some() {
95	        flag_limit
96	    } else {
97	        pos_count
98	    };
99	
100	    if let Some(c) = count {
101	        let n = c.saturating_sub(1);
102	        let both_open = spec.desc_count.is_none() && spec.anc_count.is_none();
103	        if both_open {
104	            // Split budget across both sides: ancestors get the extra
105	            let desc_n = n / 2;
106	            let anc_n = n - desc_n;
107	            spec.desc_count = Some(desc_n);
108	            spec.anc_count = Some(anc_n);
109	        } else {
110	            if spec.desc_count.is_none() {
111	                spec.desc_count = Some(n);
112	            }
113	            if spec.anc_count.is_none() {
114	                spec.anc_count = Some(n);
115	            }
116	            // bare `x 5` → treat as `x.. 5` (ancestors)
117	            if spec.desc_count == Some(0) && spec.anc_count == Some(0) {
118	                spec.anc_count = Some(n);
119	            }
120	        }
121	    }
122	
123	    spec
124	}
125	
126	/// Run a shell command. Returns stdout on success.
127	///
128	/// Logs the command at `debug!` and the process streams as follows:
129	/// - **stderr at `debug!`** on success — jj's chatter (`Moved 1 bookmarks
130	///   to …`, `Rebased N commits`, `Nothing changed.`) is hidden by default
131	///   and surfaced with `-v`. The debug formatter indents each line two
132	///   spaces so subprocess output sits visually under the caller's own
133	///   `info!` line in `-v` mode.
134	/// - **stdout at `debug!`** — callers usually consume stdout as data
135	///   (bookmark lists, commit IDs, etc.), and `info!` would flood the user
136	///   with machine-readable output they didn't ask for.
137	/// - **Failures propagate as `Err`** carrying the stderr; the caller's
138	///   error handler (`main::run_command`) surfaces it at `error!`.
139	pub fn run(cmd: &str, args: &[&str], cwd: &Path) -> Result<String, Box<dyn std::error::Error>> {
140	    let args_str = args.join(" ");
141	    debug!("$ {cmd} {args_str}");
142	    trace!("cwd: {}", cwd.display());
143	    let output = std::process::Command::new(cmd)
144	        .args(args)
145	        .current_dir(cwd)
146	        .output()
147	        .map_err(|e| format!("failed to run {cmd}: {e}"))?;
148	    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
149	    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
150	    if !stdout.is_empty() {
151	        debug!("{stdout}");
152	    }
153	    if !output.status.success() {
154	        return Err(format!("{cmd} {args_str} failed: {stderr}").into());
155	    }
156	    if !stderr.is_empty() {
157	        debug!("{stderr}");
158	    }
159	    Ok(stdout)
160	}
161	
162	/// Create a directory (and parents). Logs at debug level.
163	pub fn mkdir_p(path: &Path) -> Result<(), Box<dyn std::error::Error>> {
164	    debug!("mkdir -p {}", path.display());
165	    std::fs::create_dir_all(path)?;
166	    Ok(())
167	}
168	
169	/// Write content to a file. Logs at debug level.
170	pub fn write_file(path: &Path, content: &str) -> Result<(), Box<dyn std::error::Error>> {
171	    debug!("write {}", path.display());
172	    std::fs::write(path, content)?;
173	    Ok(())
174	}
175	
176	/// Display a prompt, read a line from stdin, and log both together.
177	/// Returns the trimmed response.
178	pub fn prompt(msg: &str) -> Result<String, Box<dyn std::error::Error>> {
179	    use std::io::Write;
180	    eprint!("{msg}");
181	    std::io::stderr().flush()?;
182	    let mut response = String::new();
183	    std::io::stdin().read_line(&mut response)?;
184	    let trimmed = response.trim().to_string();
185	    info!("{msg}{trimmed}");
186	    Ok(trimmed)
187	}
188	
189	/// Wrap text in ANSI bold escape codes.
190	pub fn bold(s: &str) -> String {
191	    format!("\x1b[1m{s}\x1b[0m")
192	}
193	
194	/// Bold only the first line of a multi-line string.
195	pub fn bold_first_line(s: &str) -> String {
196	    if let Some(pos) = s.find('\n') {
197	        format!("\x1b[1m{}\x1b[0m{}", &s[..pos], &s[pos..])
198	    } else {
199	        bold(s)
200	    }
201	}
202	
203	/// Indent all lines after the first by `n` spaces.
204	///
205	/// Returns the string unchanged if `n == 0` or there is only one line.
206	pub fn indent_body(s: &str, n: usize) -> String {
207	    if n == 0 {
208	        return s.to_string();
209	    }
210	    let pad = " ".repeat(n);
211	    let mut lines = s.lines();
212	    let mut result = match lines.next() {
213	        Some(first) => first.to_string(),
214	        None => return String::new(),
215	    };
216	    for line in lines {
217	        result.push('\n');
218	        if !line.is_empty() {
219	            result.push_str(&pad);
220	        }
221	        result.push_str(line);
222	    }
223	    result
224	}
225	
226	/// Extract the ochid trailer value from a commit description, if
227	/// present — the shared string-level parser over the commit's
228	/// description (the last trailer on a multi-ochid commit, matching
229	/// this function's previous reverse scan).
230	pub fn extract_ochid(commit: &Commit) -> Option<String> {
231	    crate::desc_helpers::extract_ochid_from_desc(commit.description())
232	}
233	
234	/// Local bookmark names pointing exactly at `commit_id`, space-separated.
235	///
