247	/// Format: changeID ochid(padded) [bookmarks |] first-line.
248	///
249	/// ochid column is left-padded to `width` characters. If no ochid, a blank
250	/// placeholder of that width is used. When `bookmarks` is non-empty it is
251	/// inserted before the title with a `|` separator (mirroring jj's
252	/// `Parent commit (@-): <chid> <hash> <bookmark> | <title>` style).
253	pub fn format_commit_with_ochid(commit: &Commit, width: usize, bookmarks: &str) -> String {
254	    let change_hex = encode_reverse_hex(commit.change_id().as_bytes());
255	    let change_short = &change_hex[..change_hex.len().min(12)];
256	    let ochid = extract_ochid(commit).unwrap_or_default(); // OK: no ochid trailer → empty string
257	    let first_line = commit.description().lines().next().unwrap_or(""); // OK: obvious
258	    let title = if first_line.is_empty() {
259	        "(no description set)"
260	    } else {
261	        first_line
262	    };
263	    if bookmarks.is_empty() {
264	        format!("{change_short}  {ochid:<width$}  {title}")
265	    } else {
266	        format!("{change_short}  {ochid:<width$}  {bookmarks} | {title}")
267	    }
268	}
