279	/// separator (mirroring jj's `<chid> <hash> <bookmark> | <title>` style).
280	pub fn format_commit_short(commit: &Commit, bookmarks: &str) -> String {
281	    let change_hex = encode_reverse_hex(commit.change_id().as_bytes());
282	    let change_short = &change_hex[..change_hex.len().min(12)];
283	    let commit_hex = commit.id().hex();
284	    let commit_short = &commit_hex[..commit_hex.len().min(12)];
285	    let first_line = commit.description().lines().next().unwrap_or(""); // OK: obvious
286	    let title = if first_line.is_empty() {
287	        "(no description set)"
288	    } else {
289	        first_line
290	    };
291	    if bookmarks.is_empty() {
292	        format!("{change_short} {commit_short} {title}")
293	    } else {
