298	/// Format: changeID commitID [bookmarks |] first-line, then remaining description lines.
299	///
300	/// Same header rules as `format_commit_short`; body lines follow unchanged.
301	pub fn format_commit_full(commit: &Commit, bookmarks: &str) -> String {
302	    let change_hex = encode_reverse_hex(commit.change_id().as_bytes());
303	    let change_short = &change_hex[..change_hex.len().min(12)];
304	    let commit_hex = commit.id().hex();
305	    let commit_short = &commit_hex[..commit_hex.len().min(12)];
306	    let desc = commit.description();
307	    if desc.is_empty() {
308	        return if bookmarks.is_empty() {
309	            format!("{change_short} {commit_short} (no description set)")
310	        } else {
311	            format!("{change_short} {commit_short} {bookmarks} | (no description set)")
312	        };
313	    }
314	    let mut lines = desc.lines();
315	    let first_line = lines.next().unwrap_or(""); // OK: obvious
316	    let mut result = if bookmarks.is_empty() {
317	        format!("{change_short} {commit_short} {first_line}")
318	    } else {
319	        format!("{change_short} {commit_short} {bookmarks} | {first_line}")
320	    };
321	    for line in lines {
322	        result.push('\n');
323	        result.push_str(line);
324	    }
325	    result
326	}
