328	/// Collect commit IDs for `..x..` (both directions) or any dot notation.
329	///
330	/// Returns `(commit_ids, anchor_index)` — the IDs in display order
331	/// (descendants closest to anchor, anchor, ancestors closest to anchor)
332	/// and the index of the anchor commit within the list.
333	///
334	/// - `desc_count`: `Some(n)` = n closest descendants, `None` = all, `Some(0)` = none
335	/// - `anc_count`: `Some(n)` = n closest ancestors, `None` = all, `Some(0)` = none
336	pub fn collect_ids(
337	    workspace: &Workspace,
338	    repo: &Arc<ReadonlyRepo>,
339	    rev: &str,
340	    desc_count: Option<usize>,
341	    anc_count: Option<usize>,
342	) -> Result<(Vec<CommitId>, usize), Box<dyn std::error::Error>> {
343	    let anchor_ids = resolve_revset(workspace, repo, rev)?;
344	    if anchor_ids.is_empty() {
345	        return Err(format!("no commit found for revision '{rev}'").into());
346	    }
347	    let anchor_id = &anchor_ids[0];
348	    let root_commit_id = repo.store().root_commit_id().clone();
349	
350	    // Descendants (closest to anchor)
351	    let mut desc_ids: Vec<CommitId> = Vec::new();
352	    if desc_count != Some(0) {
353	        let descendant_ids = resolve_revset(workspace, repo, &format!("{rev}::"))?;
354	        desc_ids = descendant_ids
355	            .into_iter()
356	            .filter(|id| *id != root_commit_id && *id != *anchor_id)
357	            .collect();
358	        if let Some(n) = desc_count {
359	            let start = desc_ids.len().saturating_sub(n);
360	            desc_ids = desc_ids[start..].to_vec();
361	        }
362	    }
363	
364	    // Ancestors (closest to anchor)
365	    let mut anc_ids: Vec<CommitId> = Vec::new();
366	    if anc_count != Some(0) {
367	        let ancestor_ids = resolve_revset(workspace, repo, &format!("::{rev}"))?;
368	        let limit = anc_count.unwrap_or(usize::MAX); // OK: no --ancestors limit → unbounded
369	        let mut count = 0;
370	        for commit_id in ancestor_ids {
371	            if commit_id == root_commit_id || commit_id == *anchor_id {
372	                continue;
373	            }
374	            anc_ids.push(commit_id);
375	            count += 1;
376	            if count >= limit {
377	                break;
378	            }
379	        }
380	    }
381	
382	    let anchor_index = desc_ids.len();
383	    let mut result = desc_ids;
384	    result.push(anchor_id.clone());
385	    result.extend(anc_ids);
386	    Ok((result, anchor_index))
387	}
