409	/// Run a closure once per resolved repo, with optional header decoration between repos.
410	///
411	/// Takes an already-resolved `&[PathBuf]` — the caller is responsible
412	/// for any flag-driven expansion (see `resolve_repos`). Continues past
413	/// errors, printing them to stderr, and returns an error if any
414	/// repo's body failed.
415	pub fn for_each_repo<F>(
416	    repos: &[PathBuf],
417	    header: &Header,
418	    mut body: F,
419	) -> Result<(), Box<dyn std::error::Error>>
420	where
421	    F: FnMut(&Workspace, &Arc<ReadonlyRepo>) -> Result<(), Box<dyn std::error::Error>>,
422	{
423	    let multi = repos.len() > 1;
424	    let mut first = true;
425	    let mut errors: Vec<String> = Vec::new();
426	
427	    for repo_path in repos {
428	        if multi {
429	            match header {
430	                Header::Label(deco) => {
431	                    if !first {
432	                        info!("");
433	                    }
434	                    info!(
435	                        "{}",
436	                        bold(&format!("{deco} {} {deco}", repo_path.display()))
437	                    );
438	                }
439	                Header::None => {}
440	            }
441	        }
442	        first = false;
443	
444	        match load_repo(repo_path) {
445	            Ok((workspace, repo)) => {
446	                if let Err(e) = body(&workspace, &repo) {
447	                    error!("({}): {e}", repo_path.display());
448	                    errors.push(format!("{}: {e}", repo_path.display()));
449	                }
450	            }
451	            Err(e) => {
452	                error!("({}): {e}", repo_path.display());
453	                errors.push(format!("{}: {e}", repo_path.display()));
454	            }
455	        }
456	    }
457	
458	    if errors.is_empty() {
459	        Ok(())
460	    } else {
461	        Err(format!("{} repo(s) had errors", errors.len()).into())
462	    }
463	}
