479	/// Parse and evaluate a revset string, returning commit IDs.
480	pub fn resolve_revset(
481	    workspace: &Workspace,
482	    repo: &Arc<ReadonlyRepo>,
483	    revset_str: &str,
484	) -> Result<Vec<CommitId>, Box<dyn std::error::Error>> {
485	    let aliases_map = RevsetAliasesMap::new();
486	    let fileset_aliases_map = FilesetAliasesMap::new();
487	    let extensions = RevsetExtensions::default();
488	    let workspace_root = workspace.workspace_root().to_path_buf();
489	    let path_converter = RepoPathUiConverter::Fs {
490	        cwd: workspace_root.clone(),
491	        base: workspace_root,
492	    };
493	    let workspace_name = workspace.workspace_name();
494	    let workspace_ctx = RevsetWorkspaceContext {
495	        path_converter: &path_converter,
496	        workspace_name,
497	    };
498	    let context = RevsetParseContext {
499	        aliases_map: &aliases_map,
500	        local_variables: HashMap::new(),
501	        user_email: "",
502	        date_pattern_context: chrono::Utc::now().fixed_offset().into(),
503	        default_ignored_remote: None,
504	        fileset_aliases_map: &fileset_aliases_map,
505	        extensions: &extensions,
506	        workspace: Some(workspace_ctx),
507	    };
508	
509	    let mut diagnostics = RevsetDiagnostics::new();
510	    let expression = jj_lib::revset::parse(&mut diagnostics, revset_str, &context)?;
511	
512	    let no_extensions: &[Box<dyn jj_lib::revset::SymbolResolverExtension>] = &[];
513	    let symbol_resolver = SymbolResolver::new(repo.as_ref(), no_extensions);
514	    let resolved = expression.resolve_user_expression(repo.as_ref(), &symbol_resolver)?;
515	    let revset = resolved.evaluate(repo.as_ref())?;
516	
517	    let mut commit_ids = Vec::new();
518	    let mut stream = revset.commit_change_ids();
519	    while let Some(result) = stream.next().block_on() {
520	        let (commit_id, _change_id) = result?;
521	        commit_ids.push(commit_id);
522	    }
523	    Ok(commit_ids)
524	}
