526	/// Scan `jj bookmark list -a <name>` output for non-tracking remote refs.
527	///
528	/// Tracked remotes appear indented (`  @origin: ...`); non-tracking remotes
529	/// appear at column 0 as `<bookmark>@<remote>: ...`. Returns the
530	/// non-tracking remote name if any is found.
531	pub fn find_non_tracking_remote(list_output: &str, bookmark: &str) -> Option<String> {
532	    let prefix = format!("{bookmark}@");
533	    for line in list_output.lines() {
534	        if line.starts_with(&prefix)
535	            && let Some(rest) = line.strip_prefix(&prefix)
536	            && let Some((remote, _)) = rest.split_once(':')
537	        {
538	            return Some(remote.to_string());
539	        }
540	    }
541	    None
542	}
543	
544	/// Scan `jj bookmark list -a <name>` output for a *tracked* entry
545	/// for `remote`.
546	///
547	/// - Tracked remotes appear indented under the local bookmark —
548	///   `  @origin: …` when synced, or the decorated divergent form
549	///   `  @origin (ahead by N commits): …`; both count as tracking.
550	/// - A column-0 `<bookmark>@<remote>: …` line is a non-tracking
551	///   ref (see `find_non_tracking_remote`), never a match here.
552	pub fn find_tracked_remote(list_output: &str, remote: &str) -> bool {
553	    let colon = format!("@{remote}:");
554	    let space = format!("@{remote} ");
555	    list_output.lines().any(|line| {
556	        line.starts_with(char::is_whitespace) && {
557	            let t = line.trim_start();
558	            t.starts_with(&colon) || t.starts_with(&space)
559	        }
560	    })
561	}
