563	/// Verify all remote refs for `bookmark` in `repo` are tracked.
564	///
565	/// Returns `Err` with the exact `jj bookmark track …` remediation command if
566	/// any non-tracking remote ref is found. Used as a preflight by repo-modifying
567	/// commands (sync, push, squash-push) and as a post-condition assertion by setup
568	/// commands (init, clone, test-fixture).
569	pub fn verify_tracking(repo: &Path, bookmark: &str) -> Result<(), Box<dyn std::error::Error>> {
570	    let all = crate::jj::bookmark_list_all(repo, bookmark)?;
571	    if let Some(remote) = find_non_tracking_remote(&all, bookmark) {
572	        let repo_str = repo.to_string_lossy();
573	        return Err(format!(
574	            "bookmark '{bookmark}' has non-tracking remote '{bookmark}@{remote}' — \
575	             run `jj bookmark track {bookmark} --remote={remote} -R {repo_str}` to fix"
576	        )
577	        .into());
578	    }
579	    Ok(())
580	}
