582	/// At-rest publish state of a bookmark vs its `@origin` counterpart.
583	#[derive(Debug, PartialEq, Eq)]
584	pub enum PublishState {
585	    /// Local bookmark and `bookmark@origin` point at the same commit.
586	    InSync,
587	    /// `bookmark@origin` does not exist — never pushed.
588	    NeverPushed,
589	    /// Local and origin point at different commits (full commit ids).
590	    Mismatch { local: String, remote: String },
591	}
592	
593	/// Resolve the at-rest publish state of `bookmark` in `repo`.
594	///
595	/// The bookmark only moves inside a push / squash-push run, which
596	/// publishes it in the same invocation — so between commands
597	/// `bookmark == bookmark@origin` is the invariant. A mismatch means
598	/// an earlier publish was lost (or origin moved out from under us).
599	///
600	/// - Read-only: two `jj log` commit-id lookups, nothing else.
601	/// - Errors when the local bookmark itself does not resolve.
602	pub fn bookmark_publish_state(
603	    repo: &Path,
604	    bookmark: &str,
605	) -> Result<PublishState, Box<dyn std::error::Error>> {
606	    let repo_str = repo.to_string_lossy();
607	    let commit_id = |rev: &str| crate::jj::cid_of(repo, rev);
608	    let local = commit_id(bookmark)
609	        .map_err(|e| format!("bookmark '{bookmark}' does not resolve in '{repo_str}': {e}"))?;
610	    // `present(...)` maps a nonexistent remote bookmark to an empty
611	    // result instead of a revset error.
612	    let remote = commit_id(&format!("present({bookmark}@origin)"))?;
613	    Ok(if remote.is_empty() {
614	        PublishState::NeverPushed
615	    } else if local == remote {
616	        PublishState::InSync
617	    } else {
618	        PublishState::Mismatch { local, remote }
619	    })
620	}
