622	/// Verify the bot repo's `bookmark` is published at origin.
623	///
624	/// Error-raising wrapper over [`bookmark_publish_state`], used by
625	/// `validate-bot` and push preflight. Fixes nothing (decided
626	/// 2026-07-15: no automatic fixing) — the error names the
627	/// `vc-x1 squash-push` resolution and the caller stops.
628	pub fn verify_bot_published(
629	    bot_repo: &Path,
630	    bookmark: &str,
631	) -> Result<(), Box<dyn std::error::Error>> {
632	    let repo_str = bot_repo.to_string_lossy();
633	    match bookmark_publish_state(bot_repo, bookmark)? {
634	        PublishState::InSync => Ok(()),
635	        PublishState::NeverPushed => Err(format!(
636	            "bot repo '{repo_str}': bookmark '{bookmark}' has never been pushed to origin — \
637	             publish it with `vc-x1 squash-push -R {repo_str}`"
638	        )
639	        .into()),
640	        PublishState::Mismatch { local, remote } => Err(format!(
641	            "bot repo '{repo_str}': '{bookmark}' ({}) does not match '{bookmark}@origin' ({}) — \
642	             an earlier publish was likely lost; publish it with \
643	             `vc-x1 squash-push -R {repo_str}`, then retry",
644	            &local[..local.len().min(12)],
645	            &remote[..remote.len().min(12)]
646	        )
647	        .into()),
648	    }
649	}
