655	///   file-relative rule);
656	/// - absolute value → taken as-is (allowed but discouraged — it
657	///   commits one machine's layout).
658	pub fn resolve_repo_path(cfg_dir: &Path, value: &str) -> PathBuf {
659	    let p = Path::new(value);
