667	/// True when `dir` is a workspace's bot repo.
668	///
669	/// Side detection is by *self-resolution*: `dir` is the bot side
670	/// iff its own `.vc-config.toml`'s `repos.bot` resolves
671	/// (file-relative) back to `dir` itself — the entry that names the
672	/// config's own directory names the side. Falls back to the
673	/// legacy location rule ([`legacy_is_bot_dir`]) so read-only
674	/// surfaces that bypass the resolvers' legacy rejection (explicit
675	/// `--other-repo` paths in validate-desc / fix-desc) still see a
676	/// legacy bot dir as the bot side. Paths are canonicalized so
677	/// relative forms and symlinked tempdirs compare correctly;
678	/// anything unreadable is "not the bot side".
679	pub fn is_bot_dir(dir: &Path) -> bool {
680	    let Ok(dir) = dir.canonicalize() else {
681	        return false;
682	    };
683	    if let Ok(cfg) = toml_simple::toml_load(&dir.join(VC_CONFIG_FILE))
684	        && let Some(bot) = toml_simple::toml_get(&cfg, "repos.bot").filter(|v| !v.is_empty())
685	    {
686	        return resolve_repo_path(&dir, bot)
687	            .canonicalize()
688	            .is_ok_and(|p| p == dir);
689	    }
690	    crate::legacy_vc_config::is_bot_dir(&dir)
691	}
