693	/// Walk up from `start` to find the workspace root (the work repo).
694	///
695	/// The nearest ancestor with a `.vc-config.toml` decides: its
696	/// `repos.work`, resolved file-relative, *is* the root — the walk
697	/// finding the bot repo's config first still lands on the work
698	/// repo (its `work` points there), so the two sides need no
699	/// nesting assumption. Returns `None` if no config is found up to
700	/// the filesystem root — the caller is in a "plain old repo" (POR)
701	/// with no vc-x1 workspace metadata.
702	///
703	/// Legacy roots — the 0.75.x root-anchored `[workspace] work`
704	/// schema and the pre-0.75.0 `path = "/"` schema — are still
705	/// *found* (pointed at the work side via the legacy location
706	/// rule), so the resolvers can reject them with a fix-it message
707	/// via `reject_legacy_config` instead of silently degrading the
708	/// workspace to POR.
709	pub fn find_workspace_root_from(start: &Path) -> Option<PathBuf> {
710	    let mut cur = start.to_path_buf();
711	    loop {
712	        let cfg = cur.join(VC_CONFIG_FILE);
713	        if let Ok(map) = toml_simple::toml_load(&cfg) {
714	            if let Some(work) = toml_simple::toml_get(&map, "repos.work") {
715	                let resolved = resolve_repo_path(&cur, work);
716	                // OK: a declared-but-missing work dir surfaces at
717	                // the resolvers' coherence checks, not here.
718	                return Some(resolved.canonicalize().unwrap_or(resolved));
719	            }
720	            if crate::legacy_vc_config::is_root_marker(&map) {
721	                return if crate::legacy_vc_config::is_bot_dir(&cur) {
722	                    cur.parent().map(Path::to_path_buf)
723	                } else {
724	                    Some(cur)
725	                };
726	            }
727	        }
728	        cur = cur.parent()?.to_path_buf();
729	    }
730	}
