732	/// Error fast on a legacy `.vc-config.toml` schema.
733	///
734	/// The topology readers treat unknown keys as absent, which would
735	/// silently degrade a dual workspace to single-repo — so every
736	/// resolver calls this first and fails with the
737	/// [`legacy_vc_config::reject`](crate::legacy_vc_config::reject)
738	/// rewrite instead. A config with both a `[repos]` registry and
739	/// stray legacy keys passes (the registry drives behavior;
740	/// `config --validate` flags the strays). Also rejects an empty
741	/// `repos.work` — every reader would silently misresolve it.
742	pub fn reject_legacy_config(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
743	    let Ok(cfg) = toml_simple::toml_load(&dir.join(VC_CONFIG_FILE)) else {
744	        return Ok(());
745	    };
746	    if let Some(msg) = crate::legacy_vc_config::reject(dir, &cfg) {
747	        return Err(msg.into());
748	    }
749	    if toml_simple::toml_get(&cfg, "repos.work").is_some_and(|w| w.is_empty()) {
750	        return Err(format!(
751	            "{}/.vc-config.toml: repos.work is empty — it must be a path \
752	             (relative to the config file's directory, e.g. \".\" in the \
753	             work repo); nothing was changed",
754	            dir.display()
755	        )
756	        .into());
757	    }
758	    Ok(())
759	}
