761	/// Cwd-anchored wrapper over [`find_workspace_root_from`].
762	pub fn find_workspace_root() -> Option<PathBuf> {
763	    let cur = std::env::current_dir().ok()?;
764	    find_workspace_root_from(&cur)
765	}
