767	/// Resolve the workspace's default `--scope`.
768	///
769	/// Reads `<workspace_root>/.vc-config.toml > repos.bot`:
770	///
771	/// - dual workspace (non-empty `bot`) → `Scope([Work, Bot])`
772	/// - single-repo workspace (missing / empty `bot`) →
773	///   `Scope([Work])`
774	/// - POR (no `workspace_root`) → `Scope([Work])` — `scope_to_repos`
775	///   resolves `Side::Work` to cwd's `.` when no root is given, so a
776	///   POR run still operates on the current directory.
777	pub fn default_scope(workspace_root: Option<&Path>) -> Scope {
778	    let Some(root) = workspace_root else {
779	        return Scope(vec![Side::Work]);
780	    };
781	    let cfg = match toml_simple::toml_load(&root.join(VC_CONFIG_FILE)) {
782	        Ok(c) => c,
783	        Err(_) => return Scope(vec![Side::Work]),
784	    };
785	    match toml_simple::toml_get(&cfg, "repos.bot") {
786	        Some(v) if !v.is_empty() => Scope(vec![Side::Work, Side::Bot]),
787	        _ => Scope(vec![Side::Work]),
788	    }
789	}
790	
791	/// Resolve a `Scope` to concrete repo paths.
792	///
793	/// - `Side::Work` → `workspace_root` (or cwd's `.` when
794	///   `workspace_root` is None).
795	/// - `Side::Bot` → the root config's `repos.bot`, resolved
796	///   file-relative against the root.
797	///
798	/// Errors when `Side::Bot` is requested but the workspace doesn't
799	/// define one (POR or single-repo workspace).
800	pub fn scope_to_repos(
801	    scope: &Scope,
802	    workspace_root: Option<&Path>,
803	) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
804	    if let Some(root) = workspace_root {
805	        reject_legacy_config(root)?;
806	    }
807	    let mut repos = Vec::new();
808	    for side in &scope.0 {
809	        match side {
810	            Side::Work => repos.push(
811	                workspace_root
812	                    .map(Path::to_path_buf)
813	                    .unwrap_or_else(|| PathBuf::from(".")),
814	            ),
815	            Side::Bot => {
816	                let root = workspace_root.ok_or(
817	                    "--scope=bot: not in a vc-x1 workspace (no .vc-config.toml with a [repos] registry) — drop --scope or use --scope=work",
818	                )?;
819	                let cfg = toml_simple::toml_load(&root.join(VC_CONFIG_FILE))?;
820	                let bot = toml_simple::toml_get(&cfg, "repos.bot")
821	                    .filter(|v| !v.is_empty())
822	                    .ok_or(
823	                        "--scope=bot: no bot repo configured. Add `bot = \"…\"` to the [repos] registry to enable dual-repo operations",
824	                    )?;
825	                repos.push(resolve_repo_path(root, bot));
826	            }
827	        }
828	    }
829	    Ok(repos)
830	}
831	
832	/// Resolve the workspace's bot-repo path, or `None` when it has no
833	/// bot side.
834	///
835	/// The scope-aware prelude for commands that *optionally* work
836	/// against the bot repo (validate-desc / fix-desc): topology comes
837	/// from `default_scope` (the workspace config), not a flag —
838	/// `Ok(None)` means a POR / single-repo workspace, the caller's
839	/// no-op case, while a configured-but-broken bot side still errors
840	/// via `scope_to_repos`.
841	pub fn bot_repo_path(workspace_root: &Path) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
842	    match configured_bot_dir(workspace_root)? {
843	        Some(bot) => {
844	            verify_workspace_coherence(workspace_root, &bot)?;
845	            Ok(Some(bot))
846	        }
847	        None => Ok(None),
848	    }
849	}
850	
851	/// The bot dir the workspace config *declares* — a pure config
852	/// read, no on-disk verification.
853	///
854	/// The pre-coherence half of [`bot_repo_path`], for callers that
855	/// resolve the dir before it exists (clone names the local clone
856	/// destination from the just-cloned work repo's config). `Ok(None)`
857	/// when the workspace declares no bot side.
858	pub fn configured_bot_dir(
859	    workspace_root: &Path,
860	) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
861	    reject_legacy_config(workspace_root)?;
862	    if !default_scope(Some(workspace_root)).has_bot() {
863	        return Ok(None);
864	    }
865	    let repos = scope_to_repos(&Scope(vec![Side::Bot]), Some(workspace_root))?;
866	    match repos.as_slice() {
867	        [bot] => Ok(Some(bot.clone())),
868	        other => Err(format!(
869	            "configured_bot_dir: expected one repo from scope_to_repos, got {}",
870	            other.len()
871	        )
872	        .into()),
873	    }
874	}
875	
876	/// Resolve the bot repo of a workspace that *requires* one.
877	///
878	/// The dual-only sibling of [`bot_repo_path`] for operations that
879	/// make no sense without a bot side (push): `None` becomes a loud
880	/// error instead of a no-op signal.
881	pub fn require_bot_dir(workspace_root: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
882	    bot_repo_path(workspace_root)?.ok_or_else(|| {
883	        format!(
884	            "{}/.vc-config.toml declares no bot repo (`repos.bot`) — \
885	             this operation requires a dual workspace",
886	            workspace_root.display()
887	        )
888	        .into()
889	    })
890	}
891	
892	/// Dual-mode entry preflight: verify the two repos' recorded
893	/// topology agrees before any operation acts on it.
894	///
895	/// Checks, in order, erroring with everything known and changing
896	/// nothing (the dual-preflight principle, 2026-07-23):
897	///
898	/// - the bot dir exists (and is a directory);
899	/// - its `.vc-config.toml` loads;
900	/// - **resolved agreement**: each side's declared `[repos]` pair,
901	///   resolved file-relative and canonicalized, names the same two
902	///   directories (the file-relative schema makes the raw blocks
903	///   asymmetric by design, so agreement is checked on resolved
904	///   reality, not spelling);
905	/// - **self-identification**: each config's own directory sits at
906	///   its side's key (root's `work`, bot's `bot`) — agreement
907	///   alone can't catch both sides naming the same wrong pair.
908	///
909	/// Mid-flight surprises stay per-operation concerns; this gates
910	/// *entry* at the one topology resolver.
911	fn verify_workspace_coherence(root: &Path, bot: &Path) -> Result<(), Box<dyn std::error::Error>> {
912	    if !bot.is_dir() {
913	        return Err(format!(
914	            "workspace incoherent: {}/.vc-config.toml declares bot repo '{}', \
915	             but that directory does not exist — fix the `bot` value or \
916	             restore the directory; nothing was changed",
917	            root.display(),
918	            bot.display()
919	        )
920	        .into());
921	    }
922	    let root_cfg = toml_simple::toml_load(&root.join(VC_CONFIG_FILE))?;
923	    let bot_cfg = toml_simple::toml_load(&bot.join(VC_CONFIG_FILE)).map_err(|e| {
924	        format!(
925	            "workspace incoherent: bot repo '{}' has no readable {VC_CONFIG_FILE} \
926	             ({e}) — both sides must carry a [repos] registry naming the same \
927	             directories; nothing was changed",
928	            bot.display()
929	        )
930	    })?;
931	    let (root_pair, bot_pair) = (
932	        resolved_repos_pair(root, &root_cfg)?,
933	        resolved_repos_pair(bot, &bot_cfg)?,
934	    );
935	    if root_pair != bot_pair {
936	        return Err(format!(
937	            "workspace incoherent: the two sides' [repos] registries resolve to \
938	             different directories — they must name the same work/bot pair; \
939	             nothing was changed\n\
940	             {}/{VC_CONFIG_FILE}: work={}, bot={}\n\
941	             {}/{VC_CONFIG_FILE}: work={}, bot={}",
942	            root.display(),
943	            root_pair.0.display(),
944	            root_pair.1.display(),
945	            bot.display(),
946	            bot_pair.0.display(),
947	            bot_pair.1.display()
948	        )
949	        .into());
950	    }
951	    // Self-identification: agreement alone can't catch both sides
952	    // naming the same *wrong* pair — each config's own directory
953	    // must sit at its side's key.
954	    let canon_root = root.canonicalize()?;
955	    if root_pair.0 != canon_root {
956	        return Err(format!(
957	            "workspace incoherent: {}/{VC_CONFIG_FILE}'s `repos.work` resolves to \
958	             '{}', not to the workspace root itself — the work side's own entry \
959	             must name its own directory; nothing was changed",
960	            root.display(),
961	            root_pair.0.display()
962	        )
963	        .into());
964	    }
965	    let canon_bot = bot.canonicalize()?;
966	    if bot_pair.1 != canon_bot {
967	        return Err(format!(
968	            "workspace incoherent: {}/{VC_CONFIG_FILE}'s `repos.bot` resolves to \
969	             '{}', not to the bot repo itself — the bot side's own entry must \
970	             name its own directory; nothing was changed",
971	            bot.display(),
972	            bot_pair.1.display()
973	        )
974	        .into());
975	    }
976	    Ok(())
977	}
978	
979	/// Resolve and canonicalize one side's declared `[repos]` pair.
980	///
981	/// The per-side half of the resolved-agreement check: reads
982	/// `repos.work` / `repos.bot` from `cfg` (the config at
983	/// `cfg_dir`), resolves each file-relative, and canonicalizes —
984	/// a missing key or unresolvable directory is its own coherence
985	/// error.
986	fn resolved_repos_pair(
987	    cfg_dir: &Path,
988	    cfg: &HashMap<String, String>,
989	) -> Result<(PathBuf, PathBuf), Box<dyn std::error::Error>> {
990	    let resolve = |key: &str| -> Result<PathBuf, Box<dyn std::error::Error>> {
991	        let value = toml_simple::toml_get(cfg, key)
992	            .filter(|v| !v.is_empty())
993	            .ok_or_else(|| {
994	                format!(
995	                    "workspace incoherent: {}/{VC_CONFIG_FILE} has no `{key}` in its \
996	                     [repos] registry — both sides must declare the work/bot pair; \
997	                     nothing was changed",
998	                    cfg_dir.display()
999	                )
1000	            })?;
1001	        resolve_repo_path(cfg_dir, value)
1002	            .canonicalize()
1003	            .map_err(|e| {
1004	                format!(
1005	                    "workspace incoherent: {}/{VC_CONFIG_FILE}'s `{key}` (\"{value}\") does \
1006	                 not resolve to an existing directory ({e}); nothing was changed",
1007	                    cfg_dir.display()
1008	                )
1009	                .into()
1010	            })
1011	    };
1012	    Ok((resolve("repos.work")?, resolve("repos.bot")?))
1013	}
1014	
1015	/// Resolve `CommonArgs.repo` + `CommonArgs.scope` into concrete repo paths.
1016	///
1017	/// The four `CommonArgs` consumers (`chid` / `desc` / `list` / `show`)
1018	/// call this at the start of their body to translate the clap surface
1019	/// into the `&[PathBuf]` that `for_each_repo` iterates. Behavior matches
1020	/// today's defaults plus a composing rule for the new `--scope` flag:
1021	///
1022	/// - neither flag → `[.]` (today's no-arg default).
1023	/// - `-R PATH` alone → `[PATH]` (today's `-R <path>` behavior;
1024	///   workspace context not consulted).
1025	/// - `-s ROLES` alone → resolves against `find_workspace_root()` —
1026	///   the surrounding workspace if there is one, else POR
1027	///   (`Side::Work` → `.`, `Side::Bot` → error).
1028	/// - `-R PATH -s ROLES` → resolves with `PATH` as the workspace root
1029	///   (overrides `find_workspace_root`). This is the composing case;
1030	///   e.g. `chid -R ../foo -s bot` queries `../foo/.claude`.
1031	///
1032	/// `--scope` is keyword-only (`work|bot|work,bot|bot,work`);
1033	/// path-based single-repo operation routes through `-R/--repo`.
1034	pub fn resolve_repos(
1035	    repo: Option<&Path>,
1036	    scope: Option<&Scope>,
1037	) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
1038	    match (repo, scope) {
1039	        (None, None) => Ok(vec![PathBuf::from(".")]),
1040	        (Some(p), None) => Ok(vec![p.to_path_buf()]),
1041	        (Some(p), Some(s)) => scope_to_repos(s, Some(p)),
1042	        (None, Some(s)) => scope_to_repos(s, find_workspace_root().as_deref()),
1043	    }
1044	}
1045	
1046	/// Resolved shared params for the read-only commit-query subcommands
1047	/// (`chid` / `desc` / `list` / `show`). Built once at the binary edge
1048	/// from `CommonArgs` via `TryFrom`; each subcommand's `XxxParams`
1049	/// embeds this.
1050	///
1051	/// - `spec` — resolved `DotSpec` (parsed `..` notation + per-side
1052	///   count budget).
1053	/// - `header` — resolved inter-repo `Header` (label vs none).
1054	/// - `repos` — resolved repo paths (`-R` + `-s` → `Vec<PathBuf>`).
1055	#[derive(Debug)]
1056	pub struct CommonParams {
1057	    pub spec: DotSpec,
1058	    pub header: Header,
1059	    pub repos: Vec<PathBuf>,
1060	}
1061	
1062	impl TryFrom<&CommonArgs> for CommonParams {
1063	    type Error = String;
1064	
1065	    /// Resolve clap `CommonArgs` into clap-free `CommonParams`: run
1066	    /// `resolve_spec` / `resolve_header` / `resolve_repos` at the
1067	    /// binary edge. Fallible because `resolve_repos` can fail
1068	    /// (workspace lookup, path issues).
1069	    fn try_from(a: &CommonArgs) -> Result<Self, String> {
1070	        let spec = resolve_spec(a.pos_rev.as_deref(), a.pos_count, &a.revision, a.limit, "@");
1071	        let header = resolve_header(&a.label, a.no_label);
1072	        let repos = a.resolve_repos().map_err(|e| e.to_string())?;
1073	        Ok(CommonParams {
1074	            spec,
1075	            header,
1076	            repos,
1077	        })
1078	    }
1079	}
1080	
1081	#[cfg(test)]
1082	mod tests;
