1	//! The three versions `--version` reports, and where each comes
2	//! from.
3	//!
4	//! They answer different questions and have different sources:
5	//!
6	//! - ours: `CARGO_PKG_VERSION`, compile time.
7	//! - jj-lib's: `JJ_LIB_VERSION`, resolved from `Cargo.lock` by
8	//!   `build.rs`, because jj-lib exports no version constant. It is
9	//!   what writes ops once the mutations move in-process, so it is
10	//!   compile-time by nature, not by compromise.
11	//! - the data's: read through jj-lib's public accessors only. What
12	//!   comes back is backend *type* names (the `.jj/repo/<backend>/type`
13	//!   files `RepoLoader::init_from_file_system` reads), because that
14	//!   is all jj-lib exposes: as of 0.43 it has no public version
15	//!   constant and no public accessor for one. The commit index does
16	//!   carry a format version, but the constant is `pub(super)` and a
17	//!   mismatch self-heals by reindexing; the op store, the thing we
18	//!   would be co-writing, carries no stamp at all.
19	
20	use std::path::Path;
21	
22	use jj_lib::config::StackedConfig;
23	use jj_lib::settings::UserSettings;
24	use jj_lib::workspace::{Workspace, default_working_copy_factories};
25	
26	use crate::common;
27	
28	/// The jj-lib version this binary links against.
29	pub fn jj_lib_version() -> &'static str {
30	    env!("JJ_LIB_VERSION")
31	}
32	
33	/// Why the gate refused to let a run touch a repo.
34	///
35	/// Three outcomes rather than one, because the fix differs: install
36	/// jj, report an unexpected `jj -V` format, or reconcile versions.
37	#[derive(Debug, Clone, PartialEq, Eq)]
38	pub enum GateError {
39	    /// `jj -V` could not be run at all.
40	    JjUnavailable(String),
41	    /// `jj -V` ran but printed something we cannot read a triple from.
42	    Unparsable(String),
43	    /// Both versions known, and different.
44	    Mismatch {
45	        /// Our linked jj-lib.
46	        ours: String,
47	        /// The `jj` on `$PATH`.
48	        theirs: String,
49	    },
50	}
51	
52	impl std::fmt::Display for GateError {
53	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
54	        match self {
55	            GateError::JjUnavailable(why) => write!(
56	                f,
