76	/// order (newest first, matching `jj log`).
77	fn commits_of(repo: &Path, revset: &str) -> Result<Vec<Commit>> {
78	    let (workspace, repo_at_head) = common::load_repo(repo)?;
79	    let ids = common::resolve_revset(&workspace, &repo_at_head, revset)?;
80	    ids.iter()
81	        .map(|id| Ok(repo_at_head.store().get_commit(id)?))
82	        .collect()
83	}
