85	/// True when `revset` matches at least one commit in `repo`.
86	///
87	/// A valid-but-empty revset (e.g. `conflicts()` on a clean repo)
88	/// is `Ok(false)`; an unresolvable revision is an `Err` — use
89	/// `rev_exists` to fold that case to `false`.
90	pub fn matches(repo: &Path, revset: &str) -> Result<bool> {
91	    if references_working_copy(revset) {
92	        return Ok(!log_spawn(repo, revset, "\"x\"")?.is_empty());
93	    }
94	    let (workspace, repo_at_head) = common::load_repo(repo)?;
95	    Ok(!common::resolve_revset(&workspace, &repo_at_head, revset)?.is_empty())
96	}
