98	/// True when `rev` resolves in `repo`.
99	///
100	/// Folds jj's unresolvable-revision error (`is_no_such_revision`,
101	/// either path) to `Ok(false)`; other failures (bad repo path,
102	/// spawn error) stay `Err`.
103	pub fn rev_exists(repo: &Path, rev: &str) -> Result<bool> {
104	    match matches(repo, rev) {
105	        Ok(found) => Ok(found),
106	        Err(e) if is_no_such_revision(e.as_ref()) => Ok(false),
107	        Err(e) => Err(e),
108	    }
