111	/// True when `e` is jj's unresolvable-revision error, in either
112	/// form: the in-process `RevsetResolutionError::NoSuchRevision`
113	/// (typed) or the spawned CLI's stderr wording (`doesn't exist`,
114	/// `No such revision`).
115	pub fn is_no_such_revision(e: &(dyn std::error::Error + 'static)) -> bool {
116	    if let Some(res) = e.downcast_ref::<RevsetResolutionError>() {
117	        return matches!(res, RevsetResolutionError::NoSuchRevision { .. });
118	    }
119	    let msg = e.to_string();
120	    msg.contains("doesn't exist") || msg.contains("No such revision")
121	}
